function signedTrackDelta(a:number,b:number,length:number){let delta=(a-b)%length;if(delta>length/2)delta-=length;if(delta<-length/2)delta+=length;return delta;}

function makeTrack(layout:TrackLayout){return new THREE.CatmullRomCurve3(layout.points.map(point=>new THREE.Vector3(...point).multiplyScalar(layout.scale)),true,"centripetal");}

const transportedFrameCache=new WeakMap<THREE.CatmullRomCurve3,{rights:THREE.Vector3[];ups:THREE.Vector3[]}>();
function transportedFrame(curve:THREE.CatmullRomCurve3,progress:number){
  let cached=transportedFrameCache.get(curve);
  if(!cached){
    const tangents=Array.from({length:SAMPLES+1},(_,index)=>curve.getTangentAt(index/SAMPLES).normalize()),rights:THREE.Vector3[]=[],ups:THREE.Vector3[]=[];
    const initialUp=new THREE.Vector3(0,1,0),initialRight=tangents[0].clone().cross(initialUp).normalize();rights.push(initialRight);ups.push(initialRight.clone().cross(tangents[0]).normalize());
    for(let index=1;index<=SAMPLES;index++){const rotation=new THREE.Quaternion().setFromUnitVectors(tangents[index-1],tangents[index]),up=ups[index-1].clone().applyQuaternion(rotation),right=tangents[index].clone().cross(up).normalize();rights.push(right);ups.push(right.clone().cross(tangents[index]).normalize());}
    const seamAxis=tangents[0],seamAngle=Math.atan2(seamAxis.dot(ups[SAMPLES].clone().cross(ups[0])),ups[SAMPLES].dot(ups[0]));for(let index=1;index<=SAMPLES;index++){const correction=seamAngle*index/SAMPLES;rights[index].applyAxisAngle(tangents[index],correction);ups[index].applyAxisAngle(tangents[index],correction);}
    cached={rights,ups};transportedFrameCache.set(curve,cached);
  }
  const scaled=((progress%1)+1)%1*SAMPLES,index=Math.floor(scaled)%SAMPLES,next=(index+1)%SAMPLES,alpha=scaled-index,forward=curve.getTangentAt(progress).normalize(),right=cached.rights[index].clone().lerp(cached.rights[next],alpha);right.addScaledVector(forward,-right.dot(forward)).normalize();return {right,up:right.clone().cross(forward).normalize()};
}

function frame(curve:THREE.CatmullRomCurve3,progress:number,layout:TrackLayout){
  const p=((progress%1)+1)%1,center=curve.getPointAt(p),forward=curve.getTangentAt(p).normalize();
  const transported=layout.verticalLoops?.length?transportedFrame(curve,p):null;
  const worldUp=Math.abs(forward.y)>.94?new THREE.Vector3(0,0,1):new THREE.Vector3(0,1,0);
  const right=transported?.right??forward.clone().cross(worldUp).normalize(),up=transported?.up??right.clone().cross(forward).normalize(),bank=magneticBank(p,layout);
  right.applyAxisAngle(forward,bank);up.applyAxisAngle(forward,bank);
  const matrix=new THREE.Matrix4().makeBasis(right,up,forward.clone().negate());
  return {center,forward,right,up,bank,quaternion:new THREE.Quaternion().setFromRotationMatrix(matrix)};
}

function createTrack(curve:THREE.CatmullRomCurve3,layout:TrackLayout){
  const positions:number[]=[],colors:number[]=[],indices:number[]=[];const base=new THREE.Color(layout.theme.track),stripe=new THREE.Color(layout.theme.stripe),magneticColor=new THREE.Color(layout.theme.magnetic);
  for(let i=0;i<=SAMPLES;i++){const progress=i/SAMPLES,f=frame(curve,progress,layout),magnetic=layout.magnetic.some(([start,end])=>progressInRange(progress,[start,end]));for(let lane=0;lane<=6;lane++){const point=f.center.clone().addScaledVector(f.right,-TRACK_WIDTH/2+lane*TRACK_WIDTH/6).addScaledVector(f.up,-.07);positions.push(point.x,point.y,point.z);const color=magnetic?magneticColor:lane===0||lane===6||(i%18<2&&lane===3)?stripe:base;colors.push(color.r,color.g,color.b);}}
  for(let i=0;i<SAMPLES;i++){const progress=(i+.5)/SAMPLES;if(isGap(progress,layout))continue;for(let lane=0;lane<6;lane++){const a=i*7+lane,b=a+1,c=a+7,d=c+1;indices.push(a,c,b,b,c,d);}}
  const geometry=new THREE.BufferGeometry();geometry.setAttribute("position",new THREE.Float32BufferAttribute(positions,3));geometry.setAttribute("color",new THREE.Float32BufferAttribute(colors,3));geometry.setIndex(indices);geometry.computeVertexNormals();
  return new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({vertexColors:true,metalness:.82,roughness:.29,emissive:0x02090f,side:THREE.DoubleSide}));
}

function tunnelHasClearance(curve:THREE.CatmullRomCurve3,progress:number){
  const center=curve.getPointAt(progress),minimumClearance=TRACK_WIDTH*1.2;
  for(let sample=0;sample<260;sample++){
    const otherProgress=sample/260,separation=Math.abs(otherProgress-progress),circularSeparation=Math.min(separation,1-separation);
    if(circularSeparation<.04)continue;
    if(center.distanceToSquared(curve.getPointAt(otherProgress))<minimumClearance*minimumClearance)return false;
  }
  return true;
}

