  const plate=(width:number,height:number,length:number,x:number,y:number,z:number,material:THREE.Material,ry=0)=>{const mesh=new THREE.Mesh(new THREE.BoxGeometry(width,height,length,2,1,3),material);mesh.position.set(x,y,z);mesh.rotation.y=ry;root.add(mesh);return mesh;};
  const engine=(x:number,z:number,radius=.28,length=.92)=>{const housing=new THREE.Mesh(new THREE.CylinderGeometry(radius*.88,radius*1.2,length,20,1,false),dark),rim=new THREE.Mesh(new THREE.TorusGeometry(radius*.82,.055,8,20),shellLight),core=new THREE.Mesh(new THREE.CircleGeometry(radius*.62,20),glow);housing.rotation.x=rim.rotation.x=core.rotation.x=Math.PI/2;housing.position.set(x,.29,z);rim.position.set(x,.29,z+length*.51);core.position.set(x,.29,z+length*.525);root.add(housing,rim,core);enginePorts.push({x,y:.29,z:z+length*.54,radius});};
