  const canopy=(x=0,z=-.42,sx=.72,sz=1.05)=>{if(cockpit)return;const bubble=new THREE.Mesh(new THREE.SphereGeometry(.62,28,14,0,Math.PI*2,0,Math.PI/2),glass);bubble.scale.set(sx,.62,sz);bubble.position.set(x,.69,z);root.add(bubble);const collar=new THREE.Mesh(new THREE.TorusGeometry(.43,.055,8,28,Math.PI),dark);collar.rotation.x=Math.PI/2;collar.rotation.z=Math.PI;collar.scale.x=sx/.72;collar.position.set(x,.54,z+.22);root.add(collar);};
  if(variant===0){planform([[0,-3.1],[.52,-2.15],[2.55,-.35],[2.18,.72],[.9,.36],[.72,2.25],[0,2.65],[-.72,2.25],[-.9,.36],[-2.18,.72],[-2.55,-.35],[-.52,-2.15]],.2,shell,.2);planform([[0,-2.72],[.36,-1.9],[.55,1.72],[0,2.2],[-.55,1.72],[-.36,-1.9]],.3,shellLight,.39);canopy();for(const side of [-1,1]){engine(side*.86,1.92,.3);lightRail(side*1.74,.05,2.25,side*.2);plate(.1,.4,1.15,side*1.16,.54,.72,dark,side*.18);}}
  else if(variant===1){planform([[0,-3.35],[.34,-2.18],[2.7,-.72],[1.7,.15],[.72,.18],[.48,2.36],[0,2.7],[-.48,2.36],[-.72,.18],[-1.7,.15],[-2.7,-.72],[-.34,-2.18]],.13,shell,.18);planform([[0,-2.95],[.28,-1.65],[.48,1.82],[0,2.22],[-.48,1.82],[-.28,-1.65]],.22,dark,.31);canopy(0,-.58,.54,.94);for(const side of [-1,1]){engine(side*.58,1.98,.21,.82);lightRail(side*1.72,-.72,2.25,side*.62);const fin=plate(.07,.66,1.2,side*1.48,.51,-.15,dark,side*.38);fin.rotation.z=side*.2;}}
  else if(variant===2){planform([[0,-2.72],[1.18,-2.05],[2.5,-1.06],[2.58,1.78],[1.64,2.48],[.58,2.28],[0,2.62],[-.58,2.28],[-1.64,2.48],[-2.58,1.78],[-2.5,-1.06],[-1.18,-2.05]],.38,shell,.25);planform([[0,-2.45],[.7,-1.68],[.92,1.36],[0,1.9],[-.92,1.36],[-.7,-1.68]],.4,shellLight,.52);canopy(0,-.25,.9,1.08);for(const side of [-1,1]){plate(.74,.55,3.5,side*1.68,.36,.46,dark);plate(.17,.24,3.25,side*2.13,.42,.38,shellLight);engine(side*1.7,2.03,.4,1.06);lightRail(side*2.22,.25,2.95);}plate(1.06,.18,.62,0,.62,1.78,dark);}
