  const body=new THREE.Mesh(new THREE.BoxGeometry(.105,.105,.34),alloy),shroud=new THREE.Mesh(new THREE.BoxGeometry(.14,.075,.18),dark),barrel=new THREE.Mesh(new THREE.CylinderGeometry(.025,.034,.27,10),alloy),grip=new THREE.Mesh(new THREE.BoxGeometry(.07,.17,.075),dark),rail=new THREE.Mesh(new THREE.BoxGeometry(.025,.018,.23),cyan),coil=new THREE.Mesh(new THREE.TorusGeometry(.061,.009,6,18),amber),muzzle=new THREE.Mesh(new THREE.RingGeometry(.018,.034,14),cyan),muzzleAnchor=new THREE.Object3D();
